    "PVC doors, windows, pipes and injection molding lines.": { en: "PVC doors, windows, pipes and injection molding lines.", zh: "PVC 门窗、管材与注塑生产线。", 'zh-TW': "PVC 門窗、管材與注塑生產線。", fr: "Lignes de portes, fenêtres, tuyaux en PVC et de moulage par injection.", es: "Líneas de puertas, ventanas, tuberías de PVC y moldeo por inyección.", de: "PVC-Türen-, Fenster-, Rohr- und Spritzgusslinien.", ar: "خطوط أبواب ونوافذ وأنابيب PVC والقولبة بالحقن.", pt: "Linhas de portas, janelas, tubos de PVC e moldagem por injeção.", ru: "Линии для ПВХ-дверей, окон, труб и литьевого формования.", ja: "PVC ドア・窓・パイプ・射出成形ライン。", ko: "PVC 도어, 창호, 파이프 및 사출 성형 라인.", it: "Linee per porte, finestre, tubi in PVC e stampaggio a iniezione." },
    "EV charger, meter, MCB breaker and SMT assembly lines.": { en: "EV charger, meter, MCB breaker and SMT assembly lines.", zh: "电动汽车充电桩、电表、断路器与 SMT 组装生产线。", 'zh-TW': "電動汽車充電樁、電錶、斷路器與 SMT 組裝生產線。", fr: "Lignes d'assemblage de chargeurs VE, compteurs, disjoncteurs MCB et SMT.", es: "Líneas de ensamblaje de cargadores para VE, medidores, disyuntores MCB y SMT.", de: "Montagelinien für EV-Ladegeräte, Zähler, MCB-Schutzschalter und SMT.", ar: "خطوط تجميع شواحن المركبات الكهربائية والعدادات وقواطع MCB وSMT.", pt: "Linhas de montagem de carregadores VE, medidores, disjuntores MCB e SMT.", ru: "Линии сборки зарядных станций для электромобилей, счётчиков, автоматов MCB и SMT.", ja: "EV充電器・メーター・MCBブレーカー・SMT組立ライン。", ko: "EV 충전기, 계량기, MCB 차단기 및 SMT 조립 라인.", it: "Linee di assemblaggio per caricabatterie EV, contatori, interruttori MCB e SMT." },
